import{_ as a,o as r,c as t,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0019 — Fréquence maximale d'un bloc dans une page : déclarée au manifeste, opposée par le serveur","description":"Extrait de docs/adr/0019-frequence-maximale-d-un-bloc-par-page.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0019 — Fréquence maximale d'un bloc dans une page : déclarée au manifeste, opposée par le serveur","description":"Extrait de docs/adr/0019-frequence-maximale-d-un-bloc-par-page.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0019-frequence-maximale-d-un-bloc-par-page.md","filePath":"developpeurs/adr/0019-frequence-maximale-d-un-bloc-par-page.md"}`),o={name:"developpeurs/adr/0019-frequence-maximale-d-un-bloc-par-page.md"};function s(i,e,l,u,c,d){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0019--fréquence-maximale-dun-bloc-dans-une-page--déclarée-au-manifeste-opposée-par-le-serveur" tabindex="-1">ADR-0019 — Fréquence maximale d&#39;un bloc dans une page : déclarée au manifeste, opposée par le serveur <a class="header-anchor" href="#adr-0019--fréquence-maximale-dun-bloc-dans-une-page--déclarée-au-manifeste-opposée-par-le-serveur" aria-label="Permalink to &quot;ADR-0019 — Fréquence maximale d&#39;un bloc dans une page : déclarée au manifeste, opposée par le serveur {#adr-0019--fréquence-maximale-dun-bloc-dans-une-page--déclarée-au-manifeste-opposée-par-le-serveur}&quot;">​</a></h1><p><strong>Date :</strong> 21 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §11.2 (« un seul bloc Localiser par page ») ; Epic E14, met en œuvre l&#39;ADR-0002</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC pose, au milieu de la description de la cartographie, une contrainte qui n&#39;est pas une contrainte de cartographie :</p><blockquote><p>Un seul bloc <strong>Localiser</strong> par page — pour des raisons de performance.</p></blockquote><p>Elle est motivée par ce que le navigateur devra charger : un moteur de rendu de carte, un jeu de tuiles, un index de clustering. Deux cartes sur une page doublent tout cela, sur des appareils dont la collectivité ne choisit pas la puissance.</p><p>Jusqu&#39;à l&#39;Epic E14, <strong>rien dans le CMS ne savait exprimer cette forme de contrainte</strong>. <code>BlockManifest</code> (E2) déclare les largeurs autorisées, le nombre d&#39;items par largeur et l&#39;imbrication ; <code>validate_page_layout()</code> les oppose bloc par bloc. Aucun de ces trois mécanismes ne regarde la page dans son ensemble, et aucun ne compte quoi que ce soit.</p><p>La question à trancher n&#39;était donc pas <em>s&#39;il fallait</em> valider la règle côté serveur — l&#39;usine à sites (CDC §9.3) recopie des pages <strong>sans repasser par l&#39;éditeur</strong>, ce qui rend toute règle purement UI contournable par le premier provisionnement de site — mais <strong>à quel niveau</strong> : une vérification spécifique au bloc cartographique, ou un mécanisme du Core que ce bloc serait le premier à utiliser.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Un <strong>mécanisme du Core</strong> : <code>BlockManifest.max_per_page: int | None</code> (<code>None</code> = pas de limite), vérifié par <code>validate_page_layout()</code> sur la composition entière. Le plugin cartographie en est le premier client, pas le propriétaire.</p><p>Quatre propriétés portent la décision :</p><ol><li><p><strong>Aucun type de bloc n&#39;est nommé dans le Core.</strong> <code>_check_page_frequency()</code> lit <code>max_per_page</code> du manifeste et compte les occurrences par clé de manifeste. Les six blocs du Core ne déclarent rien, donc restent libres — non par exception, mais parce qu&#39;ils n&#39;ont aucune borne à déclarer. Un test de recette pose deux blocs <code>text</code> sur la même page et vérifie qu&#39;ils passent : sans lui, rien ne distinguerait un mécanisme générique d&#39;un <code>if block_type == &quot;cartography.localiser&quot;</code>.</p></li><li><p><strong>Le comptage porte sur la page, pas sur l&#39;emplacement.</strong> Il descend dans les conteneurs et traverse les modules Colonne : deux cartes rangées dans deux colonnes différentes restent deux cartes que le même navigateur devra afficher.</p></li><li><p><strong><code>None</code> plutôt qu&#39;une borne par défaut.</strong> « Pas de limite » n&#39;est pas une limite haute. Une valeur par défaut, même généreuse, aurait fini par refuser une page légitime sans que rien ne l&#39;annonce — et le message d&#39;erreur aurait cité une règle que personne n&#39;a écrite.</p></li><li><p><strong>La règle est déclarée par celui qui la connaît.</strong> Le Core ne sait pas qu&#39;une carte coûte cher ; le plugin qui la fournit le sait. C&#39;est la même logique que <code>allowed_widths</code> en E2 : le manifeste rend la règle <strong>inspectable</strong> par le moteur, donc opposable à un bloc qu&#39;il n&#39;a pas écrit.</p></li></ol><p>La borne est aussi servie par <code>GET /blocks</code>, comme le reste du manifeste : l&#39;éditeur peut griser « Localiser » dans la palette quand la page en contient déjà un, plutôt que de laisser un webmaster composer une page qui sera refusée à l&#39;enregistrement.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Une vérification spécifique au bloc cartographique</strong>, dans <code>validation.py</code> ou dans le plugin</td><td>Fait entrer un nom de plugin dans le moteur du Core, ce que l&#39;ADR-0002 refuse explicitement. Et un plugin ne peut pas valider une composition de page : il n&#39;a aucun point d&#39;extension sur la validation, à raison — le SDK offrirait alors un moyen de refuser des pages pour des motifs que le Core ne peut pas inspecter.</td></tr><tr><td><strong>Documenter la règle et la tenir dans l&#39;éditeur</strong></td><td>C&#39;est ce que le CDC demande de ne pas faire pour les trois règles de composition d&#39;E2, et pour la raison exacte qui vaut ici : l&#39;usine à sites duplique des pages sans passer par l&#39;éditeur. La contrainte de performance se propagerait alors sur toute une organisation.</td></tr><tr><td><strong>Une contrainte exprimée en nombre de ressources</strong> (« au plus un bloc coûteux par page »)</td><td>Plus général en apparence, inexploitable en pratique : il faudrait un barème de coût par bloc, arbitré par qui ? Le CDC formule une règle simple et vérifiable ; l&#39;abstraire l&#39;aurait rendue invérifiable.</td></tr><tr><td><strong>Un <code>max_per_column</code> en plus</strong></td><td>Aucun besoin exprimé, et la contrainte du CDC porte explicitement sur la page. Un réglage supplémentaire sans cas d&#39;usage est un réglage que personne ne saura remplir.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>La contrainte de performance du CDC est tenue par la <strong>forme du code</strong> — une donnée de manifeste et une passe de comptage — et non par la vigilance de l&#39;éditeur ou de l&#39;intégrateur.</li><li>Le prochain bloc qui aura la même contrainte (bannière d&#39;entête, fil d&#39;Ariane, lecteur monopolisant une ressource du navigateur, futur bloc PayFiP) trouve le mécanisme déjà là et ne le réinvente pas.</li><li>Le message d&#39;erreur nomme le bloc, le nombre trouvé et la borne : un webmaster corrige sa page sans chercher quelle règle il a enfreinte, et les erreurs restent collectées en une passe comme partout ailleurs dans ce Core.</li></ul><p><strong>Négatives</strong></p><ul><li>La règle est vérifiée à l&#39;écriture de la page, pas à la mise à jour d&#39;un plugin : une page enregistrée avec deux occurrences d&#39;un bloc <strong>avant</strong> que son manifeste ne déclare <code>max_per_page=1</code> reste en base telle quelle. Elle sera refusée à la première réécriture (le Page Builder revalide intégralement à chaque écriture, y compris pour ce motif), mais aucun balayage ne la détecte d&#39;ici là. Le même trou existe déjà pour <code>allowed_widths</code> et <code>max_items</code> depuis E2 ; le combler demande un audit de composition sur tout le parc, qui n&#39;appartient pas à cet Epic.</li><li>Le comptage parcourt la composition une seconde fois, après la validation bloc par bloc. Le coût est négligeable (une page a des dizaines de blocs, pas des milliers) et le gain de lisibilité est réel : une règle qui porte sur la page entière ne se lit pas au milieu d&#39;une fonction qui juge un bloc isolé.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] <code>BlockManifest.max_per_page</code> et <code>_check_page_frequency()</code> (<code>apps/api/app/page_builder/</code>) — Epic E14, <strong>aucune migration</strong> (le manifeste est un objet Pydantic, pas une table).</li><li>[x] Premier usage : <code>max_per_page=1</code> sur le bloc <code>cartography.localiser</code> (<code>apps/api/app/bundled_plugins/cartography.py</code>).</li><li>[x] Recette : <code>test_un_seul_bloc_localiser_par_page</code>, <code>test_deux_blocs_localiser_dans_deux_colonnes_sont_refuses</code> et <code>test_deux_blocs_du_core_sur_la_meme_page_restent_acceptes</code> (<code>apps/api/tests/test_cartography.py</code>) — le troisième existe pour prouver que le mécanisme est générique.</li><li>[x] Éditeur (Nuxt, hors périmètre backend) : griser dans la palette un bloc dont la page atteint déjà sa borne, en lisant <code>max_per_page</code> de <code>GET /blocks</code>. → <strong>Close</strong> par <code>f178304</code> (21/08/2026) : <code>apps/admin/components/pagebuilder/PageBlockPalette.vue:69-77</code> rend le bloc indisponible (<code>disabled</code>, bouton grisé l.112), motif énoncé en texte (« déjà présent N fois dans la page, maximum M »). Cochée le 26/09/2026 (audit du 26/09, SUIVI-2).</li><li>[x] Epic multi-site (E10) : l&#39;usine à sites valide les pages recopiées par <code>validate_page_layout()</code> comme n&#39;importe quelle écriture — vérifié. Le provisionnement (<code>app/multisite/factory.py</code>) et la poussée d&#39;une page vers un autre site (<code>POST /replication/pages/{id}/push</code>) passent tous deux par le même point d&#39;entrée, avec le registre de blocs <strong>de l&#39;organisation</strong>. Cf. ADR-0022.</li></ul>',22)])])}const g=a(o,[["render",s]]);export{m as __pageData,g as default};
